	@Test
	void deeperCohortsPreserveDuplicatesUndefAndEagerUnionWithRepeatedHasNext() {
		int subjects = 512;
		CountingSource source = passingSource(subjects, 4);
		QueryBindingSet bound = new QueryBindingSet();
		bound.addBinding("limit", VF.createLiteral(55));
		BindingSetAssignment prefix = assignment(List.of(bound, bound, new QueryBindingSet()));
		Map<BindingSet, Integer> expected = new HashMap<>();
		for (int i = 0; i < subjects; i++) {
			for (int j = 0; j < 4; j++) {
				IRI item = VF.createIRI("urn:item:" + j);
				source.add(subject(i), MEDICATION, item);
				QueryBindingSet row = new QueryBindingSet();
				row.addBinding("subject", subject(i));
				row.addBinding("item", item);
				expected.put(new QueryBindingSet(row), 2);
				row.addBinding("limit", VF.createLiteral(55));
				expected.put(row, 4);
			}
		}
		Join fanout = new Join(type(), new Union(pattern(OBSERVATION, "item"), pattern(MEDICATION, "item")));
		Join outer = new Join(prefix, fanout);
		Filter query = new Filter(outer, new Not(new Exists(pattern(CONDITION, "local"))));
		query.setRuntimeTelemetryEnabled(true);
		outer.setRuntimeTelemetryEnabled(true);
		fanout.setRuntimeTelemetryEnabled(true);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		strategy.setTrackResultSize(true);
		QueryEvaluationStep prepared = strategy.precompile(new QueryRoot(query));
		Map<BindingSet, Integer> actual = new HashMap<>();
		try (CloseableIteration<BindingSet> rows = prepared.evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				assertThat(rows.hasNext()).isTrue();
				actual.merge(new QueryBindingSet(rows.next()), 1, Integer::sum);
			}
			assertThat(rows.hasNext()).isFalse();
		}
		assertThat(actual).isEqualTo(expected);
		assertThat(query.getLongMetricActual("adaptiveFilterCohortsActual"))
				.as("one cohort per consumed TYPE row (%s), metrics %s", source.rows(TYPE),
						query.getLongMetricsActual())
				.isEqualTo(subjects * 3L);
		assertThat(outer.getJoinLeftBindingsConsumedActual()).isEqualTo(3);
		assertThat(outer.getJoinRightIteratorsCreatedActual()).isEqualTo(3);
		assertThat(fanout.getLeftArg().getJoinLeftBindingsConsumedActual()).isEqualTo(subjects * 3L);
		assertThat(fanout.getJoinLeftBindingsConsumedActual())
				.as("existing join telemetry aggregates its own left rows and the parent's three RHS input frames")
				.isEqualTo(subjects * 3L + 3);
		assertThat(source.closed.sum()).isEqualTo(source.opened.sum());

		CloseableIteration<BindingSet> partial = prepared.evaluate(EmptyBindingSet.getInstance());
		assertThat(partial.hasNext()).isTrue();
		partial.next();
		partial.close();
		partial.close();
		assertThat(source.closed.sum()).isEqualTo(source.opened.sum());
	}

	private static BindingSetAssignment assignment(List<BindingSet> rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("limit"));
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static BindingSetAssignment immutableAssignment(String name, Value... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of(name));
		List<BindingSet> rows = new ArrayList<>();
		for (Value value : values) {
			rows.add(new ListBindingSet(List.of(name), value));
		}
		assignment.setBindingSets(List.copyOf(rows));
		return assignment;
	}

	private static void addBatchObservations(Map<BindingSet, Integer> rows, IRI subject, IRI batch) {
		for (int j = 0; j < 2; j++) {
			QueryBindingSet row = new QueryBindingSet();
			row.addBinding("batch", batch);
			row.addBinding("subject", subject);
			row.addBinding("observation", VF.createIRI("urn:observation:" + j));
			rows.put(row, 1);
		}
	}

	private static void assertRejectingPrefixAvoidsDownstreamWork(TupleExpr prefix) {
		CountingSource source = new CountingSource();
		IRI encounterPredicate = VF.createIRI("urn:encounter");
		source.add(VF.createIRI("urn:prefix"), NAME, VF.createLiteral(55));
		for (int i = 0; i < SUBJECTS; i++) {
			IRI subject = subject(i);
			IRI encounter = VF.createIRI("urn:encounter:" + i);
			source.add(subject, TYPE, SUBJECT);
			source.add(subject, encounterPredicate, encounter);
			source.add(encounter, CONDITION, VF.createIRI("urn:present"));
			for (int j = 0; j < 8; j++) {
				source.add(encounter, OBSERVATION, VF.createIRI("urn:observation:" + j));
			}
		}
		TupleExpr encounters = new StatementPattern(Var.of("subject"),
				new Var("encounterPredicate", encounterPredicate), Var.of("encounter"));
		TupleExpr observations = new StatementPattern(Var.of("encounter"),
				new Var("observationPredicate", OBSERVATION), Var.of("observation"));
		TupleExpr condition = new StatementPattern(Var.of("encounter"),
				new Var("conditionPredicate", CONDITION), Var.of("local"));
		TupleExpr query = new Filter(new Join(prefix, new Join(type(), new Join(encounters, observations))),
				new Not(new Exists(condition)));
		assertThat(evaluate(query, source)).isEmpty();
		assertThat(source.lookups(OBSERVATION))
				.as("prefix rows before the condition's input must not hide the deeper drain boundary")
				.isLessThan(SUBJECTS / 2);
		assertThat(source.closed.sum()).isEqualTo(source.opened.sum());
	}

