	void nestedFiltersInBothSuffixUnionArmsRemainAdaptive() {
		CountingSource source = passingSource(128, 2);
		for (int i = 0; i < 128; i++) {
			source.add(subject(i), MEDICATION, VF.createIRI("urn:value"));
		}
		Filter arm = new Filter(new Join(pattern(OBSERVATION, "item"), pattern(MEDICATION, "value")),
				new Not(new Exists(pattern(CONDITION, "local"))));
		Filter otherArm = arm.clone();
		TupleExpr query = new Filter(new Join(type(), new Union(arm, otherArm)),
				new Not(new Exists(pattern(CONDITION, "outerLocal"))));
		Map<BindingSet, Integer> actual = evaluate(query, source);
		assertThat(actual).hasSize(128 * 2);
		assertThat(actual.values()).allMatch(multiplicity -> multiplicity == 2);
		assertThat(arm.getStringMetricPlanned("adaptiveFilterPlacementPlanned")).contains("Complete legal cuts");
		assertThat(otherArm.getStringMetricPlanned("adaptiveFilterPlacementPlanned")).contains("Complete legal cuts");
		assertThat(arm.getStringMetricPlanned("adaptiveFilterTrackingPlanned"))
				.contains("Condition telemetry aggregates active gates");
		assertThat(source.closed.sum()).isEqualTo(source.opened.sum());
	}

